CREATE TABLE TH_EMPLOYEES (
  PERSON_ID NUMBER(19) NOT NULL,
  PERSON_NUMBER VARCHAR2(30 CHAR) NOT NULL,
  FULL_NAME VARCHAR2(240 CHAR) NOT NULL,
  EMAIL VARCHAR2(240 CHAR),
  MOBILE VARCHAR2(60 CHAR),
  BU_CODE VARCHAR2(30 CHAR),
  JOB_NAME VARCHAR2(240 CHAR),
  DEPARTMENT_NAME VARCHAR2(240 CHAR),
  POSITION_NAME VARCHAR2(240 CHAR),
  GRADE_NAME VARCHAR2(60 CHAR),
  LOCATION_CODE VARCHAR2(60 CHAR),
  ASSIGNMENT_ID NUMBER(19),
  SUPERVISOR_PERSON_ID NUMBER(19),
  ACTIVE_FLAG CHAR(1) DEFAULT 'Y' NOT NULL CHECK (ACTIVE_FLAG IN ('Y','N')),
  SYNCED_AT TIMESTAMP(3),
  CONSTRAINT TH_EMPLOYEES_PK PRIMARY KEY (PERSON_ID),
  CONSTRAINT TH_EMPLOYEES_UK1 UNIQUE (PERSON_NUMBER)
);

CREATE INDEX TH_EMPLOYEES_IX1 ON TH_EMPLOYEES (SUPERVISOR_PERSON_ID);

